 const data=new Float32Array(recordCount*56),bounds=new Float64Array(recordCount*6);let index=0;for(const item of items)for(let j=0;j<item.count;j++,index++){data.set(item.values.subarray(j*53,j*53+53),index*56);data[index*56+53]=item.component;for(let k=0;k<6;k++)bounds[index*6+k]=item.values[j*53+k];}
 onProgress('建立固定形态函数BVH');const bvh=makeStacklessFunctionSupportBVH(buildFunctionSupportBVH(bounds,{leafSize:4})),h=new Uint32Array(bvh,0,4),nodeData=new Float32Array(bvh,16,h[1]*8),orderData=new Uint32Array(bvh,16+h[1]*32,h[2]);
